include("dup.php");
$dup = new dup($profile);
LogStr("Search", 1, __FILE__, __LINE__, __FUNCTION__);
function H($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}
function DropProfile($full,$part){return ($part!=""&&strpos($full,$part)===0)?trim(substr($full,strlen($part)),"//"):$full;}
function ChopName($name){global $dup;return ($dup->Settings['shortfilenames']!=0&&strlen($name)>$dup->Settings['shortfilenames'])?"...".substr($name,strlen($name)-$dup->Settings['shortfilenames']):$name;}
function HighlightSearch($value,$search){$e=H($value);return ((string)$search=="")?$e:preg_replace("/(".preg_quote(H($search),"/").")/i","<mark>$1</mark>",$e);}
function ProfileHeader($id,$path){echo "<TR class=\"nowrap tablesorter-infoOnly\"><td colspan=7><b><a href=\"profile-view.php?profile=".intval($id)."\">".H($path)."</a></b></td></TR>\n";}
$case=false;$search="";
if(isset($_POST["search"]))$search=trim($_POST["search"]);else if(isset($_GET["search"]))$search=trim($_GET["search"]);
$search=str_replace(array("\r","\n","\0"),"",$search);
$profile=isset($_REQUEST["profile"])?intval($_REQUEST["profile"]):0;
$case=isset($_REQUEST["case"])&&intval($_REQUEST["case"])==1;
$start=isset($_REQUEST["start"])?intval($_REQUEST["start"]):0;if($start<0)$start=0;
$pageLimit=990;$queryLimit=$start+$pageLimit;
$Profiles=$dup->GetProfiles("path");
?>
<!DOCTYPE HTML><HTML><HEAD><TITLE>dup - General Search</TITLE><META CHARSET="utf-8"><META content="IE=edge,chrome=1" http-equiv="X-UA-Compatible"><META name="robots" content="noindex"><LINK REL="shortcut icon" HREF="images/dup.png"><LINK REL="stylesheet" TYPE="text/css" HREF="files/bootstrap.css"><LINK REL="stylesheet" TYPE="text/css" HREF="files/jquery-ui-1.8.24.custom.css"><LINK REL="stylesheet" TYPE="text/css" HREF="files/style.css"><LINK REL="stylesheet" TYPE="text/css" HREF="files/imgs.css"><SCRIPT TYPE="text/javascript" SRC="files/jquery-1.7.2.min.js"></SCRIPT><SCRIPT TYPE="text/javascript" SRC="files/jquery-ui-1.8.24.custom.min.js"></SCRIPT><SCRIPT TYPE="text/javascript" SRC="files/jquery.tablesorter-2.1.19.min.js"></SCRIPT><SCRIPT SRC="files/script.js"></SCRIPT><SCRIPT TYPE="text/javascript" CHARSET="utf-8">sbRoot='/';top_image_html='<img src="images/top.gif" style="width:31px; height:11px" alt="Jump to top" />';</SCRIPT><SCRIPT TYPE="text/javascript" SRC="files/jquery.scrolltopcontrol-1.1.js"></SCRIPT><SCRIPT type="text/javascript">$(document).ready(function(){$("#NAVsearch").addClass("active");$("#showListTable:has(tbody tr)").tablesorter({widgets:['saveSort','zebra','stickyHeaders']});});</SCRIPT><style>mark{background:#fff3a3;color:inherit;padding:0 2px;border-radius:2px;}</style></HEAD><BODY><?php echo PageHeader(); ?></HEADER><DIV id=contentWrapper><DIV id=content><form id=searchform name=searchform method=post action=search-general.php><H1 class=title>General Search</H1><H1 class=title>Search : <input type="text" name="search" size="30" value="<?php echo H($search); ?>"> &nbsp; Scope : <?php echo "<select name=\"profile\" id=\"profile\" class=\"input-medium\" style=\"width: 270px\">\n";echo " <option value=\"0\"".(($profile==0)?" SELECTED":"")."> Global - All Profiles</option>\n";foreach($Profiles as $v){$id=intval($v['id']);echo " <option value=\"".$id."\"".(($id==$profile)?" SELECTED":"")."> (".$id.") ".H($v['path'])." </option>\n";}echo "</select>&nbsp;Case Sensitive : <input type=checkbox name=case value=1".(($case==true)?" CHECKED":"").">";?> &nbsp;<input type=Submit value=Search></H1></form><form id=search name=search method=post action=action-files.php><input type="hidden" name="profile" value="<?php echo intval($profile); ?>"><input type="hidden" id="act" name="act" value="none"><TABLE id=showListTable class=tablesorter border=0 cellSpacing=1 cellPadding=0><THEAD><TR><TH class=nowrap>Num</TH><TH>id</TH><TH>File</TH><TH>Size</TH><TH>Modified Date</TH><TH>CRC32</TH><TH>Options</TH></TR></THEAD><TBODY><?php
$num=$start+1;$tsize=0;$seen=0;$shown=0;
if(strlen($search)>0){try{$searchValue=$case?$search:strtolower($search);$likeValue="%".$searchValue."%";foreach($Profiles as $profileInfo){$profileId=intval($profileInfo['id']);if($profile!=0&&$profileId!=$profile)continue;$ppath=isset($profileInfo['path'])?$profileInfo['path']:"";ProfileHeader($profileId,$ppath);$query="SELECT f.id,f.file,f.size,f.fdate,f.crc32,f.profile,f.link FROM files f WHERE f.profile=:profile AND ".($case?"f.file LIKE :search":"LOWER(f.file) LIKE :search")." ORDER BY f.file ASC LIMIT 0,:queryLimit;";LogStr("MySQL/SQLite: $query",3,__FILE__,__LINE__,__FUNCTION__);$sdt=$dblink->prepare($query);$sdt->bindValue(":profile",$profileId,PDO::PARAM_INT);$sdt->bindValue(":search",$likeValue,PDO::PARAM_STR);$sdt->bindValue(":queryLimit",$queryLimit,PDO::PARAM_INT);$sdt->execute();$files=$sdt->fetchAll(PDO::FETCH_ASSOC);$sdt->closeCursor();foreach($files as $row){if($seen++<$start)continue;if($shown>=$pageLimit)break;$shown++;$fid=intval($row['profile']);$rowId=intval($row['id']);$rowFile=isset($row['file'])?$row['file']:"";$rowLink=isset($row['link'])?$row['link']:"";$icon=(strlen($rowLink)>0)?"<I class=icon-magnet></I>":"<I class=icon-file></I>";$size=isset($row['size'])?intval($row['size']):0;$fdate=isset($row['fdate'])?intval($row['fdate']):0;$crc32=isset($row['crc32'])?$row['crc32']:"";$date=new DateTime("@".$fdate);$fileTitle=H($rowFile);$dropTitle=H(DropProfile($rowFile,$ppath));$shortFile=ChopName($rowFile);echo "<TR class=nowrap>\n";echo " <TD class=nowrap>".$num."</TD>\n";echo " <TD class=nowrap><span title='".(($icon=="<I class=icon-file></I>")?"File":"Symlink")."'>".$icon."</span> &nbsp; <input type=checkbox id=\"sec\" name=\"files[]\" value=\"".$rowId."\" CHECKED> ".$rowId."</TD>\n";echo " <TD class=nowrap><span title=\"".$fileTitle."\">".HighlightSearch($shortFile,$search)."</span></TD>\n";echo " <TD class=nowrap><center><span title=\"".number_format($size)." bytes\">".$dup->format_bytes($size)."</span></center></TD>\n";echo " <TD class=nowrap><span title=\"".$fdate."\">&nbsp;".$date->format('Y-m-d H:i:s')."</span></TD>\n";echo " <TD class=nowrap>".H($crc32)."</TD>\n";echo " <TD align=middle><center><a href=\"view-file.php?profile=".$fid."&file=".$rowId."\"><I class=icon-eye-open title=\"View '".$fileTitle."'\"></I></a> <b>/ <a href=\"download-files.php?profile=".$fid."&file=".$rowId."\"><I class=icon-download-alt title=\"Download '".$fileTitle."'\"></I></a> / <a href=\"action-files.php?profile=".$fid."&act=Rename&files=".$rowId."\"><I class=icon-edit title=\"Rename '".$dropTitle."'\"></I></a> / <a href=\"action-files.php?profile=".$fid."&act=Move&files=".$rowId."\"><I class=icon-share title=\"Move '".$dropTitle."'\"></I></a></b></center></TD>\n";echo "</TR>\n";$num++;$tsize+=$size;}}}catch(PDOException $ex){LogError(print_r($ex,true));header("Location: error.php");exit;}}
?></TBODY><TFOOT><TR><TH style="color:black;background-color:#dfdacf;border:1pt solid black;"><?php $base="search-general.php?search=".urlencode($search)."&profile=".intval($profile).($case?"&case=1":"");if($start>0)echo "<a href=\"".$base."&start=".max(0,$start-$pageLimit)."\">Previous</a> ";if($shown>=$pageLimit)echo "<a href=\"".$base."&start=".($start+$pageLimit)."\">Next</a>"; ?></TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;"><input type=Button Value=Inverse OnClick="checkedAll('search')"></TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;">Listed Data size :</TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;"><?php echo $dup->format_bytes($tsize); ?></TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;">Displayed Items:</TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;"><?php echo $shown; ?></TH><TH style="color:black;background-color:#dfdacf;border:1pt solid black;"><center><?php echo "<a href=\"javascript:handleClick('search','Delete')\"><I class=icon-trash title=\"Delete Selected\"></I></a> / <a href=\"javascript:handleClick('search','Rename')\"><I class=icon-edit title=\"Rename Selected\"></I></a> / <a href=\"javascript:handleClick('search','Move')\"><I class=icon-share title=\"Move Selected\"></I></a>"; ?></center></TH></TR></TFOOT></TABLE></form></DIV></DIV><?php echo PageFooter(); ?></BODY><script type="text/javascript">function checkedAll(val){var inputs=document.querySelectorAll('#'+val+' input[type="checkbox"][name="files[]"]');for(var i=0;i<inputs.length;i++)inputs[i].checked=!inputs[i].checked;}function handleClick(form,act){if(confirm("Are you sure you want to '"+act+"' all the selected files?")){document.getElementById('act').value=act;document.getElementById(form).submit();}}</script></HTML>
